package de.nevergate.fahrzeuge;
import java.util.UUID;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.GameTest;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.Items;
import net.minecraftforge.gametest.GameTestHolder;
@GameTestHolder(value=NgFahrzeuge.MOD_ID,namespace=NgFahrzeuge.MOD_ID)
public final class Dev10GameTests {
 private static NgCityEntity car(GameTestHelper h,VehicleSpec s){var c=VehicleContent.type(s).create(h.getLevel());var b=h.absolutePos(new BlockPos(1,1,1));c.setPos(b.getX()+.5,h.getLevel().getMaxBuildHeight()-12,b.getZ()+.5);c.setNoGravity(true);h.getLevel().addFreshEntity(c);return c;}
 private static Player owner(GameTestHelper h,NgCityEntity c){var p=h.makeMockPlayer();p.setUUID(UUID.randomUUID());p.getAbilities().mayBuild=true;p.getAbilities().instabuild=false;p.setPos(c.position());c.equipment.claim(p);return p;}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void roofRackConsumesItemAndPersistsBothInventories(GameTestHelper h){var c=car(h,VehicleSpec.FAMILY);var p=owner(h,c);var rack=new ItemStack(VehicleContent.RACK.get());h.assertTrue(c.systems.upgrades.tool(p,rack)&&rack.isEmpty(),"Rack installation failed");c.systems.upgrades.roof.setItem(17,new ItemStack(Items.DIAMOND,4));c.equipment.cargo.setItem(0,new ItemStack(Items.GOLD_INGOT,3));var copy=VehicleContent.NG_FAMILY.get().create(h.getLevel());copy.loadEquipment(c.getPickResult().getTag());h.assertTrue(copy.systems.upgrades.rack()&&copy.systems.upgrades.roof.getItem(17).getCount()==4&&copy.equipment.cargo.getItem(0).getCount()==3,"Rack/cargo persistence failed");p.setShiftKeyDown(true);h.assertFalse(c.systems.upgrades.tool(p,new ItemStack(VehicleContent.RACK.get())),"Loaded rack removed");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void roofViewPreventsPackingAndOwnershipChanges(GameTestHelper h){var c=car(h,VehicleSpec.CITY);var p=owner(h,c);c.systems.upgrades.tool(p,new ItemStack(VehicleContent.RACK.get()));c.systems.upgrades.roof.startOpen(p);h.assertTrue(c.equipment.hasOpeners(),"Roof viewer not counted");h.assertFalse(c.equipment.changeOwner(p,UUID.randomUUID()),"Open roof transferred");p.setShiftKeyDown(true);c.interact(p,net.minecraft.world.InteractionHand.MAIN_HAND);h.assertFalse(c.isRemoved(),"Viewed roof packed");c.systems.upgrades.roof.stopOpen(p);c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void bonnetBlocksStartAndPersistsOpenState(GameTestHelper h){var c=car(h,VehicleSpec.CITY);var p=owner(h,c);h.assertTrue(c.systems.upgrades.action(p,VehicleNetwork.HOOD_ACTION)&&!c.systems.canRun(),"Open bonnet did not prevent engine start");var t=new CompoundTag();c.systems.save(t);var copy=VehicleContent.NG_CITY.get().create(h.getLevel());copy.systems.load(t);h.assertTrue(copy.systems.upgrades.hood(),"Bonnet save failed");c.systems.upgrades.action(p,VehicleNetwork.HOOD_ACTION);h.assertTrue(c.systems.canRun(),"Closing bonnet did not permit start");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void damagedTyreLimitsSpeedAndRequiresJackToolAndSpare(GameTestHelper h){var c=car(h,VehicleSpec.CITY);var p=owner(h,c);c.systems.upgrades.impact(100);h.assertTrue(c.systems.speed(.3F,1,false,false)<=NgCityEntity.MAX_FORWARD*.35F+.001,"Flat tyre did not limit speed");var spare=new ItemStack(VehicleContent.SPARE_WHEEL.get());h.assertFalse(c.systems.upgrades.tool(p,spare),"Wheel changed without jack");h.assertTrue(c.systems.upgrades.tool(p,new ItemStack(VehicleContent.JACK.get()))&&!c.systems.canRun(),"Jack did not secure vehicle");h.assertFalse(c.systems.upgrades.tool(p,spare),"Wheel changed without wrench");p.getInventory().setItem(8,new ItemStack(VehicleContent.REPAIR_TOOL.get()));h.assertTrue(c.systems.upgrades.tool(p,spare)&&spare.isEmpty()&&c.systems.upgrades.weakest()==100,"Wheel replacement failed");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void washingNeedsWaterAndPreservesFailedPayment(GameTestHelper h){var c=car(h,VehicleSpec.CITY);var p=owner(h,c);for(int i=0;i<100;i++)c.systems.upgrades.travelled(1);h.assertTrue(c.systems.upgrades.dirt()>0,"Driving did not produce dirt");var pos=c.blockPosition().offset(3,0,0);var state=VehicleContent.WASH.get().defaultBlockState();h.getLevel().setBlockAndUpdate(pos,state);var hit=new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(pos),net.minecraft.core.Direction.UP,pos,false);h.assertFalse(state.use(h.getLevel(),p,net.minecraft.world.InteractionHand.MAIN_HAND,hit).consumesAction(),"Waterless wash succeeded");p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.WATER_BUCKET));h.assertTrue(state.use(h.getLevel(),p,net.minecraft.world.InteractionHand.MAIN_HAND,hit).consumesAction()&&c.systems.upgrades.dirt()==0&&p.getMainHandItem().is(Items.BUCKET),"Wash did not consume water/clear dirt");c.discard();h.getLevel().removeBlock(pos,false);h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void dealerRejectsLoadedSaleAndPaysExactConditionQuoteOnce(GameTestHelper h){var c=car(h,VehicleSpec.CITY);var p=owner(h,c);c.equipment.cargo.setItem(0,new ItemStack(Items.DIAMOND));h.assertFalse(VehicleDealerConfig.sell(p,c),"Loaded car sold");c.equipment.cargo.clearContent();int healthy=VehicleDealerConfig.quote(c);c.systems.damage(50);int quote=VehicleDealerConfig.quote(c);h.assertTrue(quote<healthy,"Damage did not reduce valuation");h.assertTrue(VehicleDealerConfig.sell(p,c)&&c.isRemoved()&&p.getInventory().countItem(VehicleDealerConfig.payment())==quote,"Sale payment incorrect");h.assertFalse(VehicleDealerConfig.sell(p,c),"Sold vehicle paid twice");h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void dealerRejectsForeignConnectedAndRoofLoadedVehicles(GameTestHelper h){var c=car(h,VehicleSpec.CITY);var p=owner(h,c);var other=h.makeMockPlayer();other.setUUID(UUID.randomUUID());other.setPos(c.position());h.assertFalse(VehicleDealerConfig.sell(other,c),"Foreign car sold");c.systems.upgrades.tool(p,new ItemStack(VehicleContent.RACK.get()));c.systems.upgrades.roof.setItem(0,new ItemStack(Items.DIAMOND));h.assertFalse(VehicleDealerConfig.sell(p,c),"Roof load destroyed by sale");c.systems.upgrades.roof.clearContent();c.systems.comfort.parent(UUID.randomUUID(),1);h.assertFalse(VehicleDealerConfig.sell(p,c),"Connected car sold");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void winchMovesGraduallyAndLocksTruckUntilLoaded(GameTestHelper h){var truck=car(h,VehicleSpec.TOW_TRUCK);var p=owner(h,truck);var c=car(h,VehicleSpec.CITY);c.setPos(truck.position().add(0,0,-6));c.equipment.claim(p);truck.systems.comfort.toggleRamp();h.assertTrue(VehicleRecovery.connect(truck,c,p,4),"Winch connection failed");h.assertFalse(truck.systems.canRun(),"Truck started during winching");var before=c.position();c.tick();h.assertTrue(c.position().distanceTo(before)>.01&&c.position().distanceTo(before)<=.121&&c.systems.comfort.mode()==4,"Winch teleported or did not move");for(int i=0;i<55;i++)c.tick();h.assertTrue(c.systems.comfort.mode()==2&&Math.abs(c.getY()-truck.getY()-1.1)<.1,"Winch did not finish loading");truck.discard();c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void coveredTrailerKeepsLastCargoSlotThroughPacking(GameTestHelper h){var t=VehicleContent.TRAILER.get().create(h.getLevel());t.variant(2);h.assertTrue(t.cargo.getContainerSize()==54&&t.rows()==6,"Covered trailer capacity wrong");t.cargo.setItem(53,new ItemStack(Items.DIAMOND,6));var copy=VehicleContent.TRAILER.get().create(h.getLevel());copy.loadEquipment(t.getPickResult().getTag());h.assertTrue(copy.variant()==2&&copy.cargo.getItem(53).getCount()==6&&t.getPickResult().is(VehicleContent.CANVAS_TRAILER.get()),"Covered trailer packing lost load/type");copy.variant(1);h.assertTrue(copy.rows()==3&&copy.bodyLength()<t.bodyLength(),"Box trailer geometry incorrect");h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void trailerSynchronizesTailBrakeIndicatorAndReverseSignals(GameTestHelper h){var c=car(h,VehicleSpec.FAMILY);var p=owner(h,c);var t=VehicleContent.TRAILER.get().create(h.getLevel());t.setPos(c.position().add(0,0,-4));t.setNoGravity(true);h.getLevel().addFreshEntity(t);h.assertTrue(c.systems.couple(p),"Trailer fixture failed");p.startRiding(c);c.applyAction(p,VehicleNetwork.LIGHT_ACTION);c.applyAction(p,VehicleNetwork.HAZARD_ACTION);c.applyAction(p,VehicleNetwork.ENGINE_ACTION);c.applyAction(p,VehicleNetwork.PARK_ACTION);c.acceptInput(p,VehicleNetwork.REVERSE);c.tick();t.tick();h.assertTrue(t.lights()&&t.signal()==3&&t.reversing(),"Trailer light state not synchronized");c.acceptInput(p,VehicleNetwork.BRAKE);c.tick();t.tick();h.assertTrue(t.braking(),"Trailer brake light missing");t.detach();h.assertFalse(t.reversing()||t.lights()||t.braking(),"Detached trailer retained signals");c.discard();t.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void strangerCannotChangeUpgradesAndBeaconIsTruckOnly(GameTestHelper h){var c=car(h,VehicleSpec.CITY);var p=owner(h,c);h.assertFalse(c.systems.upgrades.action(p,VehicleNetwork.BEACON_ACTION),"City gained truck beacon");var other=h.makeMockPlayer();other.setUUID(UUID.randomUUID());other.setPos(c.position());h.assertFalse(c.systems.upgrades.action(other,VehicleNetwork.HOOD_ACTION),"Stranger opened bonnet");h.assertFalse(c.systems.upgrades.tool(other,new ItemStack(VehicleContent.JACK.get())),"Stranger jacked car");var truck=car(h,VehicleSpec.TOW_TRUCK);truck.equipment.claim(p);h.assertTrue(truck.systems.upgrades.action(p,VehicleNetwork.BEACON_ACTION)&&truck.systems.upgrades.beacon(),"Truck beacon failed");c.discard();truck.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void fullInventoryRejectsSaleWithoutRemovingVehicle(GameTestHelper h){var c=car(h,VehicleSpec.CITY);var p=owner(h,c);for(int i=0;i<36;i++)p.getInventory().setItem(i,new ItemStack(Items.STONE,64));h.assertFalse(VehicleDealerConfig.sell(p,c)||c.isRemoved(),"Full-inventory sale lost car");c.discard();h.succeed();}
 @GameTest(template="forge:empty3x3x3",timeoutTicks=30)
 public static void privateRoofContentsAreSavedButNotBroadcast(GameTestHelper h){var c=car(h,VehicleSpec.CITY);var p=owner(h,c);c.systems.upgrades.tool(p,new ItemStack(VehicleContent.RACK.get()));c.systems.upgrades.roof.setItem(0,new ItemStack(Items.DIAMOND,5));c.systems.sync();h.assertFalse(c.systemTag().contains("RoofCargo"),"Private roof inventory leaked into public snapshot");var tag=new CompoundTag();c.systems.save(tag);h.assertTrue(tag.getList("RoofCargo",10).size()==1,"Private inventory not persisted");c.discard();h.succeed();}
}
